use super::types::ProjectionPlane;
use crate::mesh::types::Point;

pub(super) fn dominant_projection_plane(a: Point, b: Point, c: Point) -> ProjectionPlane {
    let ab = (b.x - a.x, b.y - a.y, b.z - a.z);
    let ac = (c.x - a.x, c.y - a.y, c.z - a.z);
    let normal = (
        ab.1 * ac.2 - ab.2 * ac.1,
        ab.2 * ac.0 - ab.0 * ac.2,
        ab.0 * ac.1 - ab.1 * ac.0,
    );
    let nx = normal.0.abs();
    let ny = normal.1.abs();
    let nz = normal.2.abs();
    if nz >= nx && nz >= ny {
        ProjectionPlane::Xy
    } else if ny >= nx {
        ProjectionPlane::Xz
    } else {
        ProjectionPlane::Yz
    }
}

pub(super) fn project2(p: Point, plane: ProjectionPlane) -> robust::Coord<f64> {
    match plane {
        ProjectionPlane::Xy => robust::Coord { x: p.x, y: p.y },
        ProjectionPlane::Xz => robust::Coord { x: p.x, y: p.z },
        ProjectionPlane::Yz => robust::Coord { x: p.y, y: p.z },
    }
}

/// Centroid-in-triangle test in the dominant projection plane, boundary
/// inclusive. Assumes `p` is coplanar with `abc`.
pub(super) fn centroid_in_triangle_2d(p: Point, a: Point, b: Point, c: Point) -> bool {
    let plane = dominant_projection_plane(a, b, c);
    let p2 = project2(p, plane);
    let a2 = project2(a, plane);
    let b2 = project2(b, plane);
    let c2 = project2(c, plane);
    let ab = robust::orient2d(a2, b2, p2);
    let bc = robust::orient2d(b2, c2, p2);
    let ca = robust::orient2d(c2, a2, p2);
    (ab >= 0.0 && bc >= 0.0 && ca >= 0.0) || (ab <= 0.0 && bc <= 0.0 && ca <= 0.0)
}
